  VALUES ('scale', 'I lose interest when my partner becomes too emotionally dependent.', '“Emotionally dependent” means your partner relies on you heavily for reassurance, mood regulation, or identity, in a way that feels like pressure or responsibility. Rate your typical reaction: does increased dependence reduce attraction/interest for you? Answer honestly; this is used to tailor relationship and intimacy guidance.', 27, true, '08012', 'active')
  RETURNING id INTO v_q_id;
  INSERT INTO survey_question_mapping (survey_id, question_id) VALUES (v_survey_id, v_q_id);

  -- Q28: 09013 (scale)
  INSERT INTO survey_question (type, question, subinfo, display_order, required, frontend_qid, status)
  VALUES ('scale', 'I sometimes use flirtation/sex to influence the dynamic or get needs met.”', 'This is about using sexuality as leverage (to gain closeness, avoid conflict, get reassurance, feel secure, gain power, or steer the relationship). It doesn’t mean you’re “bad”; it’s a pattern some people use under stress. Answer based on real behavior, not intention. If it happens rarely, choose a lower number.', 28, true, '09013', 'active')
  RETURNING id INTO v_q_id;
  INSERT INTO survey_question_mapping (survey_id, question_id) VALUES (v_survey_id, v_q_id);

  -- Q29: 10002 (single)
  INSERT INTO survey_question (type, question, subinfo, display_order, required, frontend_qid, status)
  VALUES ('single', 'During intimacy, how do you prefer to communicate your needs and desires?', 'Answer for what feels best and most natural in the moment (not what you think you should do). “Nonverbal/quiet” = little talking. “Touch/movement” = guiding hands, pressure, pace. “Short phrases” = brief cues like “slower,” “yes,” “right there.” “Ongoing verbal feedback” = frequent talking about what feels good. “Relational check-ins” = naming feelings and connection needs (comfort, reassurance, emotional attunement) during intimacy.', 29, true, '10002', 'active')
  RETURNING id INTO v_q_id;
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'Mostly nonverbal / quiet', 'Mostly nonverbal / quiet', 1);
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'Mainly through touch/movement', 'Mainly through touch/movement', 2);
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'Short clear phrases (“slower / like that”)', 'Short clear phrases (“slower / like that”)', 3);
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'Expressive, ongoing verbal feedback', 'Expressive, ongoing verbal feedback', 4);
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'Emotionally transparent + relational check-ins', 'Emotionally transparent + relational check-ins', 5);
  INSERT INTO survey_question_mapping (survey_id, question_id) VALUES (v_survey_id, v_q_id);

  -- Q30: 10003 (scale)
  INSERT INTO survey_question (type, question, subinfo, display_order, required, frontend_qid, status)
  VALUES ('scale', 'I’m comfortable expressing what turns me on.', 'Rate your comfort in real situations: can you share desires (words, texts, guiding touch) without strong embarrassment or fear of judgment? Include both during sex and outside of sex. Answer based on typical comfort, not your best-day confidence.', 30, true, '10003', 'active')
  RETURNING id INTO v_q_id;
  INSERT INTO survey_question_mapping (survey_id, question_id) VALUES (v_survey_id, v_q_id);

  -- Q31: 10004 (scale)
  INSERT INTO survey_question (type, question, subinfo, display_order, required, frontend_qid, status)
  VALUES ('scale', 'I’m comfortable expressing what I don’t want.', 'This is about stating limits clearly (saying no, slowing down, redirecting, naming boundaries) without freezing, fawning, or feeling guilty. Rate your usual ability, especially in the moment.', 31, true, '10004', 'active')
  RETURNING id INTO v_q_id;
  INSERT INTO survey_question_mapping (survey_id, question_id) VALUES (v_survey_id, v_q_id);

  -- Q32: 10005 (scale)
  INSERT INTO survey_question (type, question, subinfo, display_order, required, frontend_qid, status)
  VALUES ('scale', 'If my partner is quiet/neutral during sex, my arousal drops.', '“Quiet/neutral” means minimal reaction, little sound, little feedback, hard to read. Rate whether you reliably lose arousal in that situation, even if touch continues. This is about your nervous system response, not about blaming your partner.', 32, true, '10005', 'active')
  RETURNING id INTO v_q_id;
  INSERT INTO survey_question_mapping (survey_id, question_id) VALUES (v_survey_id, v_q_id);

  -- Q33: 11001 (single)
  INSERT INTO survey_question (type, question, subinfo, display_order, required, frontend_qid, status)
  VALUES ('single', 'Which dynamic feels most natural?', 'This is about the flow of influence during sex (who initiates, guides, sets pace). “Lead/direct” can be gentle or firm. “Surrender/be led” means you relax more when someone else guides. “Switching” means you genuinely like both depending on mood/partner. “Egalitarian/no roles” means you prefer co-leading without clear roles. Choose what feels easiest and most energizing, not what feels politically correct.', 33, true, '11001', 'active')
  RETURNING id INTO v_q_id;
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'I like to lead/direct', 'I like to lead/direct', 1);
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'I like to surrender/be led', 'I like to surrender/be led', 2);
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'I like switching depending on mood', 'I like switching depending on mood', 3);
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'I prefer egalitarian/no roles', 'I prefer egalitarian/no roles', 4);
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'Not sure / depends a lot', 'Not sure / depends a lot', 5);
  INSERT INTO survey_question_mapping (survey_id, question_id) VALUES (v_survey_id, v_q_id);

  -- Q34: 11002 (scale)
  INSERT INTO survey_question (type, question, subinfo, display_order, required, frontend_qid, status)
  VALUES ('scale', 'I enjoy clear structure/protocol/rules in sexual dynamics.', '“Structure/protocol/rules” can be light (a routine, a sequence, agreements like “ask before escalation”) or more formal (roles, rituals, clear scripts). Rate whether clear structure makes sex feel safer, hotter, or easier for you.', 34, true, '11002', 'active')
  RETURNING id INTO v_q_id;
  INSERT INTO survey_question_mapping (survey_id, question_id) VALUES (v_survey_id, v_q_id);

  -- Q35: 11003 (single)
  INSERT INTO survey_question (type, question, subinfo, display_order, required, frontend_qid, status)
  VALUES ('single', 'In sex I most naturally…', 'Choose what you tend to do by default when you’re not overthinking. “Partner’s pleasure first” means you prioritize their experience and often take responsibility for it. “Mutual balance” means you track both equally. “Prefer receiving/being guided” means you relax and enjoy more when you’re the focus or when you’re being led. Choose “Varies” only if there’s no clear default across time/partners.', 35, true, '11003', 'active')
  RETURNING id INTO v_q_id;
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'Focus on my partner’s pleasure first', 'Focus on my partner’s pleasure first', 1);
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'Focus on mutual balance', 'Focus on mutual balance', 2);
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'Prefer receiving/being guided', 'Prefer receiving/being guided', 3);
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'It varies a lot', 'It varies a lot', 4);
