  INSERT INTO survey_question_mapping (survey_id, question_id) VALUES (v_survey_id, v_q_id);

  -- Q37: 14020 (single)
  INSERT INTO survey_question (type, question, subinfo, display_order, required, frontend_qid, status)
  VALUES ('single', 'What most reliably motivates you to want sex?', 'Pick the main reason you seek sex when it’s at its best for you (your primary driver). “Motivates” means what pulls you toward sex, not what makes sex good once you’re already in it. If two feel true, choose the one that most consistently initiates your desire. Quick definitions: Bonding = closeness; Pleasure/play = fun/body enjoyment; Novelty = newness; Intensity/edge = charge/thrill; Validation = feeling desired; Power = leading/surrendering; Meaning = sacred/union; Comfort = routine closeness; Service = giving pleasure; Healing/repair = soothing after stress/conflict; Escape = turning off your mind/world.', 37, true, '14020', 'active')
  RETURNING id INTO v_q_id;
