  -- Q54: 16005 (single)
  INSERT INTO survey_question (type, question, subinfo, display_order, required, frontend_qid, status)
  VALUES ('single', 'When you reflect on your current sexuality and pleasure, which description feels most true for you?', 'Think of this as your current season, not a permanent label. Choose the phase that best describes your baseline most days lately (past 4–8 weeks), even if you sometimes fluctuate.', 54, true, '16005', 'active')
  RETURNING id INTO v_q_id;
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'Recharging / Pausing – I’m in a quieter, restorative phase of my sexual life. Desire feels gentle or distant, and that’s okay. I sense I’m gathering energy, letting my body and mind rest before passion naturally reawakens.', 'Recharging / Pausing – I’m in a quieter, restorative phase of my sexual life. Desire feels gentle or distant, and that’s okay. I sense I’m gathering energy, letting my body and mind rest before passion naturally reawakens.', 1);
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'Repairing / Reconnecting – I’m rebuilding my relationship to sexuality, healing from past pain, shame, or disconnection. My focus is on safety, trust, and emotional openness — learning to feel at home in my body again.', 'Repairing / Reconnecting – I’m rebuilding my relationship to sexuality, healing from past pain, shame, or disconnection. My focus is on safety, trust, and emotional openness — learning to feel at home in my body again.', 2);
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'Awakening / Exploring – I feel curious and alive with possibility. I’m discovering what turns me on, learning through play and experimentation, and beginning to express my desires with more ease and honesty.', 'Awakening / Exploring – I feel curious and alive with possibility. I’m discovering what turns me on, learning through play and experimentation, and beginning to express my desires with more ease and honesty.', 3);
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'Expanding / Experimenting – I feel confident and expressive in my sexuality. I enjoy exploring new experiences, sensations, and dynamics, communicating openly about my desires, and co-creating pleasure with my partner(s).', 'Expanding / Experimenting – I feel confident and expressive in my sexuality. I enjoy exploring new experiences, sensations, and dynamics, communicating openly about my desires, and co-creating pleasure with my partner(s).', 4);
  INSERT INTO answer_option (survey_question_id, option_text, option_value, display_order)
  VALUES (v_q_id, 'Grounded / Integrated - I experience sexuality as a stable, integrated part of my life. Desire feels steady and familiar. Pleasure arises naturally in connection, routine, or self-care. This phase is about maintaining fulfillment with presence and appreciation, rather than chasing newness or repair.', 'Grounded / Integrated - I experience sexuality as a stable, integrated part of my life. Desire feels steady and familiar. Pleasure arises naturally in connection, routine, or self-care. This phase is about maintaining fulfillment with presence and appreciation, rather than chasing newness or repair.', 5);
