  VALUES (v_q_id, 'Evolving / Transcending – I experience sexuality as a deeper, transformative force — a way to connect with creativity, love, and spirituality. Pleasure feels like presence, flow, and expansion beyond the physical.', 'Evolving / Transcending – I experience sexuality as a deeper, transformative force — a way to connect with creativity, love, and spirituality. Pleasure feels like presence, flow, and expansion beyond the physical.', 6);
